Which error logs? I suspect it might be from obmc-console-client?

Is your issue fixed by this patch?

```
diff --git a/console-client.c b/console-client.c
index 67d163abb779..5a5bce800a0e 100644
--- a/console-client.c
+++ b/console-client.c
@@ -219,6 +219,7 @@ static int client_init(struct console_client *client, struct config *config,
        const char *resolved_id = NULL;
        struct sockaddr_un addr;
        socket_path_t path;
+       size_t addrlen;
        ssize_t len;
        int rc;

@@ -249,7 +250,8 @@ static int client_init(struct console_client *client, struct config *config,
                return 0;
        }

-       console_socket_path_readable(&addr, len, path);
+       addrlen = sizeof(addr) - sizeof(addr.sun_path) + len;
+       console_socket_path_readable(&addr, addrlen, path);
        warn("Can't connect to console server '@%s'", path);
 cleanup:
```
